/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: AlbumItem
 *   Functions: stub, mount, section, withPrimaryArtist, confirmClear
 *   Constants: tracksPath, uploadOnly, plainRows
 *   Variables: writes
 * Tests
 *   - an Album page lists its members in Album order with metadata, states and links to their own catalog pages
 *   - the section rereads on a later page Refresh, but a remount after an earlier one reads only once
 *   - a failed member read retries from the section and from the page Refresh, and other kinds never read members
 *   - the strict member schema refuses private fields, unknown states and misnumbered or repeated members
 *   - an expected tracklist lists its rows by Disc then Track Number, marks rows without a file and keeps each member's Album-order number
 *   - clearing the expected tracklist confirms what it removes, sends only the clear at the Album revision and rereads the tracks
 *   - a refused clear shows the conflict and rereads the rows, and an unconfirmed one retries the identical body
 *   - a confirmed clear whose reread fails keeps the saved Album, cannot clear the rows still shown and retries the section read
 *   - a stale clear is refused as a conflict and rereads the rows, and Refresh rereads the Album before its tracks, whose clear sends the newer revision
 *   - a newer Album revision read on return to the page keeps Clear disabled until the tracks read after it lands
 *   - a truncated Album lists its tracklist rows without calling any row without a file, and its clear names only the tracklist
 *   - rows without a file show durations rounded to whole seconds, and a row two members share lists both in Album order
 *   - without catalog editing the tracklist shows no Clear, and the section alone assumes no Credits
 * @end-catalog */

import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider, focusManager } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { AdminCatalogPage } from './AdminCatalogPage';
import AdminRouter from './AdminRouter';
import { CatalogAlbumTracks as CatalogAlbumTracksSection } from './CatalogAlbumTracks';
import { catalogAlbumTracksSchema, type CatalogAlbumTracks } from './catalogAlbumTracksApi';
